Các phương án, image_prompt nguyên văn và hash do ứng dụng cấp: [{"candidate_id": "R2-B2-C1", "batch_id": "B2", "revision": 2, "title": "Váy Liền Thân Mùa Hè - Cổ Giao Lĩnh Cách Tân & Họa Tiết Sen Ngực Áo", "image_prompt": "Tạo một bản minh họa thiết kế thời trang (Fashion Sketch) vẽ một chiếc váy liền thân nữ mùa hè thanh lịch dành cho sự kiện thời trang, mang chủ đề kết hợp truyền thống và hiện đại. Thiết kế váy sử dụng phom suông nhẹ gọn gàng kết hợp chi tiết cổ áo cách tân lấy cảm hứng từ cổ áo giao lĩnh chéo nhẹ nhàng tinh tế. Chất liệu váy là sự kết hợp cao cấp giữa lụa tơ tằm mềm mại và linen tự nhiên tạo độ đứng phom vừa phải, thoáng mát. Bảng màu là tone pastel hồng phấn ngọt ngào, mát mẻ cho mùa hè. Điểm nhấn là họa tiết hoa sen cách điệu theo đường nét hiện đại, được thêu tay tối giản ở một bên góc ngực áo. Toàn bộ thể hiện dưới dạng tranh phác thảo thời trang nghệ thuật sắc nét, sang trọng, thời trang quốc tế, một khung hình duy nhất.", "design_sections": [{"domain_id": "bối_cảnh_và_chủ_đề", "description": "Váy liền thân nữ mùa hè dành cho sự kiện thời trang, chủ đề truyền thống kết hợp hiện đại, trình bày theo phong cách bản minh họa thiết kế thời trang (Fashion Sketch).", "related_atom_ids": ["atom_dress_type_context", "atom_opt_fashion_illustration"]}, {"domain_id": "phom_dáng_và_chi_tiết", "description": "Phom váy suông nhẹ gọn gàng, cổ áo cách tân lấy cảm hứng từ giao lĩnh, họa tiết hoa sen cách điệu thêu tối giản ở ngực áo.", "related_atom_ids": ["atom_viet_phuc_inspiration", "atom_opt_co_ao_doi_lap", "atom_opt_hoa_tiet_sen_cach_dieu"]}, {"domain_id": "tiêu_chí_thẩm_mỹ_và_sử_dụng", "description": "Sử dụng chất liệu lụa tơ tằm kết hợp linen cao cấp, bảng màu pastel hồng phấn nhẹ nhàng, đảm bảo thoải mái, sang trọng và phong cách quốc tế.", "related_atom_ids": ["atom_usability_and_style", "atom_opt_silk_linen", "atom_opt_pastel_nhe_nhang"]}], "fashion_summary": "Thiết kế váy liền thân suông nhẹ mùa hè với cổ giao lĩnh cách tân gọn gàng, mang lại sự thoải mái, thanh lịch và đậm chất thời trang quốc tế.", "art_summary": "Thể hiện dưới dạng bản minh họa thiết kế thời trang (Fashion Sketch) tinh tế, nổi bật họa tiết hoa sen thêu tối giản trên nền lụa tơ tằm kết hợp linen tông hồng pastel.", "culture_summary": "Gợi nhắc nét đẹp Việt phục thông qua chi tiết cổ áo giao lĩnh và họa tiết hoa sen truyền thống được xử lý hiện đại, gọn gàng.", "choices_made": ["Chọn phom váy liền thân suông nhẹ kết hợp cổ áo giao lĩnh cách tân", "Chọn chất liệu lụa tơ tằm và linen cao cấp", "Chọn bảng màu pastel hồng phấn", "Chọn họa tiết hoa sen cách điệu thêu tối giản ở ngực áo", "Chọn phong cách bản minh họa thiết kế thời trang (Fashion Sketch)"], "claims": [], "locked_coverage": [{"atom_id": "atom_dress_type_context", "prompt_quote": "Thiết kế váy liền thân nữ mùa hè dành cho sự kiện thời trang, mang chủ đề kết hợp truyền thống và hiện đại."}, {"atom_id": "atom_usability_and_style", "prompt_quote": "thoải mái, thanh lịch và đậm chất thời trang quốc tế."}, {"atom_id": "atom_opt_co_ao_doi_lap", "prompt_quote": "chi tiết cổ áo cách tân lấy cảm hứng từ cổ áo giao lĩnh chéo nhẹ nhàng tinh tế."}, {"atom_id": "atom_opt_silk_linen", "prompt_quote": "Chất liệu váy là sự kết hợp cao cấp giữa lụa tơ tằm mềm mại và linen tự nhiên"}, {"atom_id": "atom_opt_pastel_nhe_nhang", "prompt_quote": "Bảng màu là tone pastel hồng phấn ngọt ngào, mát mẻ cho mùa hè."}, {"atom_id": "atom_opt_hoa_tiet_sen_cach_dieu", "prompt_quote": "họa tiết hoa sen cách điệu theo đường nét hiện đại, được thêu tay tối giản ở một bên góc ngực áo."}, {"atom_id": "atom_opt_fashion_illustration", "prompt_quote": "bản minh họa thiết kế thời trang (Fashion Sketch)"}], "assumptions": ["Sử dụng tone hồng phấn đại diện cho bảng màu pastel nhẹ nhàng mùa hè cho phương án này."], "limitations": ["Chất liệu lụa tơ tằm kết hợp linen cần xử lý độ lót phù hợp để đảm bảo tính ứng dụng cao."], "content_hash": "6b7bcdbde836b27b55c83fa4b9038b48fbab94f9bb48b9c9b8aee627013ac50f"}, {"candidate_id": "R